using AiBox.DevPortal.Models.Agents;

namespace AiBox.DevPortal.Services.Agents;


/// <summary>
/// Contains constants and methods for agent action profiles.
/// </summary>public static class AgentActionProfiles
{

/// <summary>
/// Key for the create plan action.
/// </summary>public const string CreatePlanActionKey = "create-plan";

/// <summary>
/// Key for the generate patch preview action.
/// </summary>public const string GeneratePatchPreviewActionKey = "generate-patch-preview";

/// <summary>
/// Key for the apply patch action.
/// </summary>public const string ApplyPatchActionKey = "apply-patch";

/// <summary>
/// Key for the rollback patch action.
/// </summary>public const string RollbackPatchActionKey = "rollback-patch";

/// <summary>
/// Key for the run command action.
/// </summary>public const string RunCommandActionKey = "run-command";

/// <summary>
/// Key for the verify project action.
/// </summary>public const string VerifyProjectActionKey = "verify-project";

/// <summary>
/// Key for the commit changes action.
/// </summary>public const string CommitChangesActionKey = "commit-changes";

/// <summary>
/// Key for the build and deploy action.
/// </summary>public const string BuildDeployActionKey = "build-deploy";


/// <summary>
/// Returns the agent mode for create plan action.
/// </summary>public static AgentMode ForCreatePlan() => AgentMode.Planner;

/// <summary>
/// Returns the agent mode for generate patch preview action.
/// </summary>public static AgentMode ForGeneratePatchPreview() => AgentMode.PatchBuilder;

/// <summary>
/// Returns the agent mode for verify project action.
/// </summary>public static AgentMode ForVerifyProject() => AgentMode.Verifier;

/// <summary>
/// Returns the agent mode for review diff action.
/// </summary>public static AgentMode ForReviewDiff() => AgentMode.Reviewer;

/// <summary>
/// Returns the agent mode for apply patch action.
/// </summary>public static AgentMode ForApplyPatch() => AgentMode.ToolRunner;

/// <summary>
/// Returns the agent mode for rollback patch action.
/// </summary>public static AgentMode ForRollbackPatch() => AgentMode.ToolRunner;

/// <summary>
/// Returns the agent mode for run command action.
/// </summary>public static AgentMode ForRunCommand() => AgentMode.ToolRunner;

/// <summary>
/// Returns the agent mode for commit changes action.
/// </summary>public static AgentMode ForCommitChanges() => AgentMode.ToolRunner;

/// <summary>
/// Returns the agent mode for build and deploy action.
/// </summary>public static AgentMode ForBuildDeploy() => AgentMode.ToolRunner;
}
